import React from 'react';
import { Mail, Linkedin, Github, ArrowUpRight, Send } from 'lucide-react';
export default function Contact({ sent, submitContact }) {
  return (
<section className="contact-section" id="contact"><div className="section-wrap contact-inner"><div className="section-label">05 / CONTACT</div><div className="contact-grid"><div><h2>Have a role<br/>or project in <span className="gradient-text">mind?</span></h2><p className="section-lead">I'm open to entry-level opportunities, internships and conversations with people building great products.</p><div className="contact-direct"><a href="mailto:your.email@example.com"><Mail size={17}/> your.email@example.com <ArrowUpRight size={15}/></a><a href="https://www.linkedin.com/" target="_blank" rel="noreferrer"><Linkedin size={17}/> LinkedIn profile <ArrowUpRight size={15}/></a><a href="https://github.com/" target="_blank" rel="noreferrer"><Github size={17}/> GitHub profile <ArrowUpRight size={15}/></a></div></div><form className="contact-form" onSubmit={submitContact}><label>Your name<input name="name" placeholder="Enter your name" required/></label><label>Email address<input name="email" type="email" placeholder="you@example.com" required/></label><label>Message<textarea name="message" rows="4" placeholder="Tell me a little about the opportunity..." required/></label><button className="button button-primary" type="submit">Send a message <Send size={16}/></button>{sent && <p className="form-hint">Your email app should open with the message. Update the email placeholder in the source first.</p>}</form></div></div></section>
  );
}
